base='E:\\projects\\\u5185\u5bb9\u521b\u4f5c\\\u6545\u4e8b\u77ed\u7247\\\u767d\u7c73\u996d\\\u540e\u671f\\\u5bfc\u6f14\u540e\u671f\u4fee\u6b63-v001'
mp=project.GetMediaPool()
t=project.GetCurrentTimeline()
assert t.GetName()==data['timeline'] and len(t.GetItemListInTrack('video',1) or [])==0
def allclips(f):
 a=f.GetClipList()
 for sub in f.GetSubFolderList():a+=allclips(sub)
 return a
lookup={c.GetClipProperty('File Path').replace('\\','/'):c for c in allclips(mp.GetRootFolder()) if c.GetClipProperty('File Path')}
existing={}
receipt=[]
for s in data['edl']:
 c=lookup[s['source'].replace('\\','/')]
 item=existing.get(s['name'])
 if item is None:item=mp.AppendToTimeline([{'mediaPoolItem':c,'startFrame':s['in'],'endFrame':s['out'],'recordFrame':s['record'],'trackIndex':1,'mediaType':1}])[0]
 item.SetName(s['name'])
 if abs(s['speed']-100)>.0001:
  ok=item.SetSpeed({'Percentage':s['speed'],'RippleTimeline':True,'PitchCorrection':False})
  assert ok,('speed_failed',s['name'])
 if s['props']:assert item.SetProperties({'TransformEnabled':True,**s['props']}),s['name']
 item.SetProperties({'RetimeAndScalingEnabled':True,'RetimeProcess':resolve.RETIME_OPTICAL_FLOW if s['speed']<95 else resolve.RETIME_NEAREST,'MotionEstimation':resolve.MOTION_EST_ENHANCED_BETTER})
 for attempt in range(4):
  actual=item.GetDuration()
  if actual==s['frames']:break
  rate=item.GetSpeed()['Percentage']*actual/s['frames']
  item.SetSpeed({'Percentage':round(rate,2),'RippleTimeline':True})
 receipt.append({'name':s['name'],'start':item.GetStart(),'end':item.GetEnd(),'duration':item.GetDuration(),'expected':s['frames'],'source_start':item.GetSourceStartFrame(),'source_end':item.GetSourceEndFrame(),'speed':item.GetSpeed()})
 assert item.GetStart()==s['record'] and item.GetDuration()==s['frames'],receipt[-1]
for b in data['batches']:
 t.AddMarker(b['start'],'Blue','Batch %02d %s'%(b['batch'],b['id']),'Director edit candidate; original retained',b['frames'])
for n in ['B17_GB014_01','B21_GB016-1_02','B25_GB018_01','B40_GB030-1_01','B42_GB031_02']:
 c=next(c for c in t.GetItemListInTrack('video',1) if c.GetName()==n)
 assert c.ImportFusionComp(base+'/'+n+'.comp'),n
assert t.GetEndFrame()==data['frames']
result={'items':receipt,'timeline_end':t.GetEndFrame(),'save':resolve.GetProjectManager().SaveProject()}